fn api_permission(
    api: &str,
    surface: ApiSurfaceKind,
    name: &str,
    action: PermissionAction,
) -> PermissionAtom {
    PermissionAtom::new(
        PermissionTarget::api_surface(api, surface, name).expect("generated API target"),
        action,
    )
    .expect("generated API permission")
}

fn resource_permission(
    participant: &str,
    kind: ParticipantResourceKind,
    name: &str,
    action: PermissionAction,
) -> PermissionAtom {
    PermissionAtom::new(
        PermissionTarget::participant_resource(participant, kind, name)
            .expect("generated resource target"),
        action,
    )
    .expect("generated resource permission")
}

